import{_ as t,o as r,c as l,ah as e}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"플라톤","slug":"플라톤","link":"#플라톤","children":[]},{"level":2,"title":"아리스토텔레스","slug":"아리스토텔레스","link":"#아리스토텔레스","children":[]},{"level":2,"title":"데카르트","slug":"데카르트","link":"#데카르트","children":[]},{"level":2,"title":"로크","slug":"로크","link":"#로크","children":[]}],"relativePath":"philosophy/Epistemology/09. 중간고사 복습 Q&A.md","filePath":"philosophy/Epistemology/09. 중간고사 복습 Q&A.md"}'),n={name:"philosophy/Epistemology/09. 중간고사 복습 Q&A.md"};function s(a,o,i,p,g,h){return r(),l("div",null,[...o[0]||(o[0]=[e('<blockquote><p>중간고사(플라톤~로크) 자가 테스트용 문답. 7문제 5점씩, 약술형(부분점수 있음).</p></blockquote><h2 id="플라톤" tabindex="-1">플라톤 <a class="header-anchor" href="#플라톤" aria-label="Permalink to &quot;플라톤&quot;">​</a></h2><p><strong>Q1. 보편자와 개별자의 관계는? (실재론/유명론)</strong><br> 보편자는 비물질적이며 완전히 독립적으로 실재함. 가시계에서 지각되는 개별적 대상들은 보편자에 의존적임 — 아름다운 대상은 보편자로서의 &#39;미&#39;의 본성을 분유하는 한에서 실재함. 속성은 일시적이기 때문에 개별적 대상 자체에 대해 진정한 지식을 가질 수는 없지만, 개별자는 오히려 우리로 하여금 지식을 갈망하게 만드는 존재임.</p><p><strong>Q2. 진정한 앎을 얻는 방법은?</strong><br> 동굴의 비유에서는 묶여있던 사슬을 끊고 동굴 밖으로 나가는 행위로, 선분의 비유에서는 가시계에서 가지계로의 전환을 통해 앎을 얻음. 이러한 앎은 감각이 아니라 상기를 통해 얻어짐 — 영혼은 육체와 연결되기 전 이데아에 존재했고, 현상계로 내려오며 지식을 잃었으나, 지적 활동을 통해 그 지식을 상기함으로써 진정한 앎에 가까워짐.</p><h2 id="아리스토텔레스" tabindex="-1">아리스토텔레스 <a class="header-anchor" href="#아리스토텔레스" aria-label="Permalink to &quot;아리스토텔레스&quot;">​</a></h2><p><strong>Q1. 딜레마 두 가지와 아리스토텔레스의 해결</strong></p><ol><li>보편자에 대한 확실한 지식을 태어날 때부터 가지고 있다면, 그 지식을 가졌다는 사실 자체를 전혀 의식하지 못하는 것은 이상함</li><li>아무런 사전지식 없이 지식을 습득하는 것이라면, 어떤 기초 위에서 배우고 이해할 수 있는가</li></ol><p>→ 해결: 경험을 통해 직접적으로 지식을 얻을 수 있는 <strong>감각능력</strong>이 존재함. 감각능력은 개별자에 작용하지만 그 내용은 보편자에 대한 것 — 반복적인 감각지각을 통해 보편자와 그 위계에 대한 지식으로 나아갈 수 있음.</p><p><strong>Q2. 극복해야 할 두 사상과 그 대안</strong></p><ol><li><strong>플라톤의 주지주의 거부</strong>: 플라톤은 인식의 기초가 감각이 아닌 순수한 지적 활동에 있다고 봄 → 아리스토텔레스는 지식이 선천적인 것이 아니라 감각지각으로부터 온다고 결론 내림</li><li><strong>프로타고라스의 상대주의 거부</strong>: 감각에 기초한 판단이 모두 참이 될 수 있다는 입장(감각 사이를 비교·판단할 필요가 없다는 주장) → 아리스토텔레스는 <strong>고유감각</strong> 개념을 도입 — 각 감각에는 고유한 대상이 있고, 그 대상에 대한 해당 감각의 판단이 다른 감각의 판단보다 우선함 (예: 색은 시각이, 맛은 미각이 우선)</li></ol><p><strong>Q3. 본질적 속성은 어떻게 인식하는가</strong><br> 4원인(형상인·질료인·작용인·목적인) 중 <strong>형상인과 목적인</strong>을 인식함으로써 본질적 속성을 인식할 수 있음. 이 인식에는 지성이 필요하며, 사물이 존재하는 원인을 앎으로써 그 본질적 속성을 안다고 할 수 있음.</p><h2 id="데카르트" tabindex="-1">데카르트 <a class="header-anchor" href="#데카르트" aria-label="Permalink to &quot;데카르트&quot;">​</a></h2><p><strong>Q1. 데카르트 철학 이후 고대 철학과 비교해 바뀐 점 (코기토 중심)</strong><br> 물음의 초점이 대상이 아닌 <strong>주체</strong>로 향하게 됨 — 외부세계나 대상이 아니라, 의심하고 사유하는 &#39;나&#39;의 존재를 철학의 제1원리로 삼음으로써 철학의 중심이 대상에서 주체로 이동함.</p><p><strong>Q2. 데카르트의 아르키메데스적 기획이란?</strong><br> 아르키메데스가 지구를 움직이기 위해 단 하나의 확고부동한 점만 찾으려 했듯, 데카르트도 학문의 확고한 토대를 세우기 위해 &quot;확실하고 흔들리지 않는 최소한의 것&quot;을 발견하려 함 — 하나의 확실한 진리를 발견하고 그것을 토대로 모든 학문의 체계를 재건축하기 위해서.</p><h2 id="로크" tabindex="-1">로크 <a class="header-anchor" href="#로크" aria-label="Permalink to &quot;로크&quot;">​</a></h2><p><strong>Q1. 본유관념 반대논증</strong></p><ol><li>모든 인류가 동의하는 진리가 있다 해도, 그 보편적 동의에 이르는 다른 방법(경험 등)이 있다면 그것이 본유적이라는 증명은 되지 않음</li><li>애초에 어떤 관념에 대해서도 보편적 동의란 존재하지 않음 — 어린아이나 백치는 특정 명제에 대한 최소한의 이해도 못하는 경우가 있고, 만약 어떤 관념이 영혼에 새겨져 있다면 이들도 알고 있어야 함</li></ol><p><strong>Q2. 지식으로서의 지위에 대한 로크의 입장 (표상주의·경험주의 중심)</strong></p><ol><li>경험론자로서 감각경험이 지식의 유일한 원천이라고 주장</li><li>로크의 관념이론은 표상주의로 나타남 — 마음은 외부 대상을 직접 인식하지 않고, 마음의 관념을 매개물로 삼아 인식함</li></ol><p><strong>Q3. 로크의 관념 정의</strong><br> 지성의 대상이 되는 것은 무엇이든 관념 — 심상, 개념, 상 등. 마음-독립적 대상이 아니라 <strong>심적 작용의 대상</strong>이라는 의미로 정의가 전환됨.</p><p><strong>Q4. 측연선의 비유</strong><br> 측연선(수심을 재는 추)으로 바다 전체를 알 수는 없어도 항해사에게는 큰 도움이 되듯, 우리의 마음의 힘으로 모든 사물을 알 수는 없어도 우리의 행위와 관련된 것을 아는 데는 충분히 도움이 됨.</p>',21)])])}const d=t(n,[["render",s]]);export{c as __pageData,d as default};
